def test_season_entire_current_canonical_oracle_has_full_production_coverage():
    import json
    from pathlib import Path

    from app.rules import coverage
    data=next(c for c in json.loads((Path(__file__).parent/'fixtures/exile_outcomes42_cards.json').read_text()) if c['name']=='Season of the Bold')
    result=coverage.of_card_data(data)
    assert result.level=='FULL',result.manual_parts
